/// <summary>
/// 675_TM Carrier instructions by bankaak
/// </summary>
[Form]
public class METWarehouseCustomerCarrier extends FormRun
{
    Query           query;
    CustTable       custTable;
    QueryBuildRange endDateRange;
    QueryBuildRange startDateRange;
    TransDate       defaultDate;

}

    /// <summary>
    /// Form initialize method
    /// </summary>
    public void init()
    {
        super();

        if (element.args().callerName() == menuItemDisplayStr(CustTable))
        {
            custTable = element.args().record();
        }
        else
        {
            throw Error("@SYS104799");
        }
        defaultDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
        DateControl.enabled(false);
    }

        /// <summary>
        /// Datasource execute query method
        /// </summary>
        public void executeQuery()
        {
        
            this.queryBuildDataSource().clearRanges();

            query = this.query();

            endDateRange = SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(METWarehouseCarrierCustomerView)), fieldNum(METWarehouseCarrierCustomerView, DataAreaId));

            if (ShowFilter.valueStr() == enum2Str(METShowActiveDate::Active))
            {
                endDateRange.value(strFmt('(((%1.%2 == %4) || (%1.%2 >= %5)) && (%1.%3 <= %5))',
                                        query.dataSourceTable(tablenum(METWarehouseCarrierCustomerView)).name(),
                                        fieldStr(METWarehouseCarrierCustomerView, EndDate),
                                        fieldStr(METWarehouseCarrierCustomerView, StartDate),
                                        date2StrXpp(dateNull()),
                                        date2StrXpp(defaultDate)));
            }
            else if (ShowFilter.valueStr() == enum2Str(METShowActiveDate::AsOfDate))
            {
                endDateRange.value(strFmt('(((%1.%2 == %4) || (%1.%2 >= %5)) && (%1.%3 <= %5))',
                                        query.dataSourceTable(tablenum(METWarehouseCarrierCustomerView)).name(),
                                        fieldStr(METWarehouseCarrierCustomerView, EndDate),
                                        fieldStr(METWarehouseCarrierCustomerView, StartDate),
                                        date2StrXpp(dateNull()),
                                        date2StrXpp(DateControl.dateValue())));
            }

            super();

        }

        /// <summary>
        /// Selection change method to be used when any value change in combobox
        /// </summary>
        /// <returns>Integer reference</returns>
        public int selectionChange()
        {
            int ret;
    
            if (ShowFilter.valueStr() == enum2Str(MetShowActiveDate::AsOfDate))
            {
                DateControl.dateValue(defaultDate);
                DateControl.enabled(true);
            }
            else
            {
                DateControl.dateValue(dateNull());
                DateControl.enabled(false);
            }

            ret = super();

            METWarehouseCarrierCustomerView_ds.executeQuery();
            return ret;
        }

    /// <summary>
    /// Modified method for date field
    /// </summary>
    /// <returns>Bllean value reference</returns>
    public boolean modified()
    {
        boolean ret;

        ret = super();
        METWarehouseCarrierCustomerView_ds.executeQuery();
        return ret;
    }
